package com.finance.controller;
import com.finance.repository.TransactionRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/reports") public class ReportController {private final TransactionRepository tx;public ReportController(TransactionRepository t){tx=t;}
 @GetMapping("/summary") public Map<String,Object> summary(@RequestParam(defaultValue="") String month,Authentication a){YearMonth ym=month.isBlank()?YearMonth.now():YearMonth.parse(month);var rows=tx.findByUserIdAndDateBetween((String)a.getPrincipal(),ym.atDay(1),ym.atEndOfMonth());long income=0,expense=0;Map<String,Long> cats=new LinkedHashMap<>();for(var t:rows){if("income".equals(t.getType()))income+=t.getAmountPaise();else{expense+=t.getAmountPaise();cats.merge(t.getCategory(),t.getAmountPaise(),Long::sum);}}return Map.of("month",ym.toString(),"incomePaise",income,"expensePaise",expense,"balancePaise",income-expense,"transactionCount",rows.size(),"categoryExpenses",cats);}
 @GetMapping("/yearly") public Map<String,Object> yearly(@RequestParam(defaultValue="") String year,Authentication a){int y=year.isBlank()?Year.now().getValue():Integer.parseInt(year);var rows=tx.findByUserIdAndDateBetween((String)a.getPrincipal(),LocalDate.of(y,1,1),LocalDate.of(y,12,31));List<Map<String,Object>> months=new ArrayList<>();long totalIncome=0,totalExpense=0;for(int m=1;m<=12;m++){long income=0,expense=0;for(var t:rows){if(t.getDate().getMonthValue()!=m)continue;if("income".equals(t.getType()))income+=t.getAmountPaise();else expense+=t.getAmountPaise();}totalIncome+=income;totalExpense+=expense;months.add(Map.of("month",String.format("%02d",m),"incomePaise",income,"expensePaise",expense));}return Map.of("year",y,"incomePaise",totalIncome,"expensePaise",totalExpense,"balancePaise",totalIncome-totalExpense,"months",months);}

}
